'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { 
  HomeIcon, 
  BuildingOfficeIcon, 
  ShoppingCartIcon,
  AdjustmentsHorizontalIcon,
  ChartBarIcon,
  Cog6ToothIcon,
  ArrowRightOnRectangleIcon,
  UserIcon
} from '@heroicons/react/24/outline';
import { cn } from '@/lib/utils';

const navigation = [
  { name: 'Dashboard', href: '/', icon: HomeIcon },
  { name: 'Point of Sale', href: '/pos', icon: ShoppingCartIcon },
  { name: 'Customers', href: '/customers', icon: UserIcon },
  { name: 'Branches', href: '/branches', icon: BuildingOfficeIcon },
  { name: 'Analytics', href: '/analytics', icon: ChartBarIcon },
  { name: 'Settings', href: '/settings', icon: Cog6ToothIcon },
];

interface SidebarProps {
  onClose?: () => void;
}

export default function Sidebar({ onClose }: SidebarProps) {
  const pathname = usePathname();

  const handleLogout = () => {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    window.location.href = '/login';
  };

  return (
    <div className="flex flex-col h-screen bg-surface border-r border-divider">
      {/* Logo */}
      <div className="flex items-center h-16 px-4 bg-card border-b border-divider shrink-0">
        <div className="flex items-center space-x-3">
          <div className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center shrink-0">
            <span className="text-white text-sm font-bold">P</span>
          </div>
          <h1 className="text-xl font-bold text-primary hidden sm:block">POS Admin</h1>
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-2 py-4 space-y-1 overflow-y-auto">
        {navigation.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.name}
              href={item.href}
              onClick={onClose}
              className={cn(
                'group flex items-center px-3 py-2.5 text-sm font-medium rounded-lg transition-all duration-200',
                isActive
                  ? 'bg-primary text-white shadow-sm'
                  : 'text-text-secondary hover:bg-surface hover:text-primary hover:shadow-sm'
              )}
            >
              <item.icon
                className={cn(
                  'mr-3 h-5 w-5 transition-colors shrink-0',
                  isActive ? 'text-white' : 'text-text-secondary group-hover:text-primary'
                )}
                aria-hidden="true"
              />
              <span className="truncate">{item.name}</span>
            </Link>
          );
        })}
      </nav>

      {/* User Info & Logout */}
      <div className="p-2 border-t border-divider shrink-0">
        <div className="px-3 py-2 mb-2">
          <div className="flex items-center space-x-3">
            <div className="w-8 h-8 bg-primary/10 rounded-lg flex items-center justify-center shrink-0">
              <span className="text-primary text-sm font-bold">A</span>
            </div>
            <div className="hidden sm:block min-w-0 flex-1">
              <p className="text-sm font-medium text-primary truncate">Admin User</p>
              <p className="text-xs text-text-secondary truncate">admin@ecotracker.com</p>
            </div>
          </div>
        </div>
        <button
          onClick={handleLogout}
          className="group flex items-center w-full px-3 py-2.5 text-sm font-medium text-text-secondary rounded-lg hover:bg-surface hover:text-primary hover:shadow-sm transition-all duration-200"
        >
          <ArrowRightOnRectangleIcon className="mr-3 h-5 w-5 text-text-secondary group-hover:text-primary shrink-0" />
          <span className="truncate">Logout</span>
        </button>
      </div>
    </div>
  );
}
